def all_zero_rects(grid):
    """Return list of (area, top, bottom, left, right) for every maximal-width run
    of all-zero columns for each (top,bottom) row band."""
    R, C = len(grid), len(grid[0])
    rects = []
    for top in range(R):
        ok = [grid[top][c] == 0 for c in range(C)]
        for bottom in range(top, R):
            if bottom > top:
                ok = [o and grid[bottom][c] == 0 for c, o in enumerate(ok)]
            run = 0
            for c in range(C + 1):
                if c < C and ok[c]:
                    run += 1
                else:
                    if run > 0:
                        rects.append((run * (bottom - top + 1), top, bottom, c - run, c - 1))
                    run = 0
    return rects


def interior(rect):
    _, t, b, l, r = rect
    return [(i, j) for i in range(t + 1, b) for j in range(l + 1, r)]


def diff_cells(inp, outp):
    return [(i, j) for i, row in enumerate(outp) for j, v in enumerate(row)
            if v != inp[i][j]]


print("=== Hypothesis: fill interior (shrink-by-1) of the largest all-zero rectangle with 8 ===")
for k, (inp, outp) in enumerate(EXAMPLES, 1):
    rects = all_zero_rects(inp)
    mx = max(r[0] for r in rects)
    bests = [r for r in rects if r[0] == mx]
    d = set(diff_cells(inp, outp))
    print(f"\nExample {k}: grid {len(inp)}x{len(inp[0])}, max area={mx}, "
          f"#max-area rects={len(bests)}")
    for r in bests:
        print(f"   rect rows {r[1]}-{r[2]}, cols {r[3]}-{r[4]} "
              f"({r[2]-r[1]+1}x{r[4]-r[3]+1}), interior cells = {len(interior(r))}")
        inter = set(interior(r))
        print(f"   interior == output-8s diff? {inter == d}  "
              f"(diff size {len(d)}, interior size {len(inter)})")
    # also show top-5 rectangles by area for context
    top5 = sorted(rects, key=lambda x: -x[0])[:5]
    print("   top rects by area:", [(a, f"r{t}-{b}", f"c{l}-{rr}") for a, t, b, l, rr in top5])

